import{_ as n,C as e,o as s,c as d,E as a,a7 as c}from"./chunks/framework.FWlv_suP.js";const g=JSON.parse('{"title":"Radio Bee Privacy Policy","description":"Privacy Policy for the Radio Bee application.","frontmatter":{"title":"Radio Bee Privacy Policy","description":"Privacy Policy for the Radio Bee application."},"headers":[],"relativePath":"apps/radio-bee/privacy.md","filePath":"apps/radio-bee/privacy.md"}'),l={name:"apps/radio-bee/privacy.md"};function p(h,o,u,m,y,b){const r=e("AppBreadcrumbs"),t=e("AppSubnav"),i=e("CopyStandaloneUrl");return s(),d("div",null,[a(r,{"app-id":"radio-bee",current:"Privacy"}),a(t,{"app-id":"radio-bee"}),a(i,{path:"/privacy/radio-bee",label:"Copy Play Store URL","copied-label":"Play Store URL copied","document-name":"Radio Bee privacy policy"}),o[0]||(o[0]=c('<h1 id="privacy-policy-for-radio-bee" tabindex="-1">Privacy Policy for Radio Bee <a class="header-anchor" href="#privacy-policy-for-radio-bee" aria-label="Permalink to &quot;Privacy Policy for Radio Bee&quot;">​</a></h1><p><strong>Effective Date:</strong> November 22, 2026<br><strong>Last Updated:</strong> November 22, 2026</p><h2 id="about-radio-bee" tabindex="-1">About Radio Bee <a class="header-anchor" href="#about-radio-bee" aria-label="Permalink to &quot;About Radio Bee&quot;">​</a></h2><p>Radio Bee (RadioBee) is an internet-radio station directory and player developed by <strong>Anand Raja</strong>. This policy applies to the Radio Bee Android app distributed through Google Play and its <a href="https://actionanand.github.io/radio-bee/" target="_blank" rel="noreferrer">web app</a>.</p><p>Radio Bee helps you discover and listen to radio stations operated by third parties. It does not operate those broadcasters or control their separate privacy practices. You do not need a Radio Bee account to listen.</p><h2 id="information-stored-on-your-device" tabindex="-1">Information stored on your device <a class="header-anchor" href="#information-stored-on-your-device" aria-label="Permalink to &quot;Information stored on your device&quot;">​</a></h2><p>Radio Bee may save favorites, preferred language, theme, selected home stations, browsing and filter preferences, and cached station catalogue information in local browser or app storage. These settings support the app&#39;s functions and are not uploaded to a developer-operated account or synchronization service.</p><p>Android and your browser may also maintain ordinary WebView, media, network, and cache data according to their own controls.</p><h2 id="network-access-and-third-party-radio-streams" tabindex="-1">Network access and third-party radio streams <a class="header-anchor" href="#network-access-and-third-party-radio-streams" aria-label="Permalink to &quot;Network access and third-party radio streams&quot;">​</a></h2><p>Radio Bee uses the internet to retrieve station catalogue and application resources, including resources hosted on GitHub Pages, and to connect to the station you choose. Playback generally requests audio directly from the relevant broadcaster or streaming host.</p><p>When these connections occur, the destination provider may receive standard technical request information, such as IP address, browser or device details, stream or resource URL, and request time. Providers may keep logs and may operate in other countries. Their privacy practices, retention, and use of cookies or similar technologies are controlled by them, not by Radio Bee.</p><p>Station websites or external links that you choose to open are governed by their own terms and privacy policies.</p><h2 id="contact-form" tabindex="-1">Contact form <a class="header-anchor" href="#contact-form" aria-label="Permalink to &quot;Contact form&quot;">​</a></h2><p>The optional <strong>Contact Us</strong> form is submitted using <strong>Google Forms</strong>. If you submit a request, the information you enter is transmitted to Google for processing and made available to the Radio Bee operator. This includes your <strong>name, email address, inquiry purpose</strong>, and any details you provide, such as an optional phone number, message, station name, stream URL, website, country, city, frequency, or language.</p><p>This information is used to respond to support, feedback, station-correction, and rights-related inquiries. The form requests your consent before submission. Do not submit passwords or sensitive personal documents. Google&#39;s processing is subject to its <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Privacy Policy</a>.</p><h2 id="advertising-analytics-and-sharing" tabindex="-1">Advertising, analytics, and sharing <a class="header-anchor" href="#advertising-analytics-and-sharing" aria-label="Permalink to &quot;Advertising, analytics, and sharing&quot;">​</a></h2><p>The reviewed Radio Bee application does not include a developer-operated user-account service, in-app advertising SDK, or developer-operated analytics service. Radio Bee does not sell your locally stored preferences.</p><p>Your device does transmit network request information to the services needed for station catalogues and streaming, as described above. Contact details that you deliberately submit are processed by Google Forms and the Radio Bee operator. Third-party services may have independent logging practices.</p><h2 id="android-permissions" tabindex="-1">Android permissions <a class="header-anchor" href="#android-permissions" aria-label="Permalink to &quot;Android permissions&quot;">​</a></h2><p>The Android app requires internet connectivity for station discovery and playback. Internet access is a normal Android permission and does not prompt for runtime approval. The public listening features do not require access to your location, camera, microphone, contacts, SMS, phone call history, or broad device storage.</p><h2 id="retention-deletion-and-your-choices" tabindex="-1">Retention, deletion, and your choices <a class="header-anchor" href="#retention-deletion-and-your-choices" aria-label="Permalink to &quot;Retention, deletion, and your choices&quot;">​</a></h2><p>You can remove locally stored Radio Bee preferences and cache by clearing the app&#39;s storage or uninstalling it. For the web app, clear site data in your browser. These actions do not delete information independently held by broadcasters, hosting services, or Google.</p><p>Contact submissions may be retained by the form operator as needed to handle inquiries and applicable obligations. To request access, correction, or deletion of a form submission, email <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong> with enough information to identify the submission. Requests are reviewed subject to applicable law and retention requirements; a request cannot necessarily remove third-party network logs.</p><p>For instructions, see <a href="https://actionanand.github.io/policy-hub/data-deletion/radio-bee" target="_blank" rel="noreferrer">Radio Bee data deletion</a>.</p><h2 id="children" tabindex="-1">Children <a class="header-anchor" href="#children" aria-label="Permalink to &quot;Children&quot;">​</a></h2><p>Radio Bee is a general-audience radio directory, not a service specifically designed for children. Its contact form is not intended to solicit personal information from children. Parents and guardians should supervise access to external radio services where appropriate.</p><h2 id="updates-and-contact" tabindex="-1">Updates and contact <a class="header-anchor" href="#updates-and-contact" aria-label="Permalink to &quot;Updates and contact&quot;">​</a></h2><p>We may update this policy if app features or information practices change. Updates will be published on this page with a revised date.</p><p><strong>Developer:</strong> Anand Raja<br><strong>Privacy and support:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></p>',29))])}const v=n(l,[["render",p]]);export{g as __pageData,v as default};
